# Step 1.5 — Class-specific symmetric agreement

class_agreement = pd.DataFrame({
    "Pass 1 tasks": confusion_matrix.sum(axis=1),
    "Pass 2 tasks": confusion_matrix.sum(axis=0),
    "Agreed tasks": [
        confusion_matrix.loc[label, label] for label in order
    ],
})
class_agreement["Specific agreement"] = (
    2 * class_agreement["Agreed tasks"]
    / (class_agreement["Pass 1 tasks"] + class_agreement["Pass 2 tasks"])
)
display(
    class_agreement.style.format({
        "Specific agreement": "{:.1%}"
    })

